package in.recallradar;
import org.springframework.http.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException; import java.time.*;
@Service @Transactional class InvitationService {private final TeamInvitationRepository invitations;private final UserRepository users;private final MembershipRepository members;private final RefreshRepository refreshes;private final TenantService tenants;private final TokenService tokens;private final PasswordEncoder passwords;private final AppProperties props;private final AuditService audit;InvitationService(TeamInvitationRepository i,UserRepository u,MembershipRepository m,RefreshRepository re,TenantService t,TokenService to,PasswordEncoder p,AppProperties pr,AuditService a){invitations=i;users=u;members=m;refreshes=re;tenants=t;tokens=to;passwords=p;props=pr;audit=a;}
InvitationResponse create(Membership actor,InvitationRequest r){tenants.requireAdmin(actor);var raw=tokens.opaque();var invite=invitations.save(new TeamInvitation(actor.organizationId,r.email().trim().toLowerCase(),r.role(),tokens.hash(raw)));audit.record(actor,"TEAM_INVITE_CREATED","TEAM_INVITATION",invite.id,"Invited "+invite.email);return new InvitationResponse(invite.email,invite.role,raw,"/?invite="+raw);}
TokenResponse accept(AcceptInvitationRequest r){var invite=invitations.findByTokenHash(tokens.hash(r.token())).filter(x->x.acceptedAt==null&&x.expiresAt.isAfter(Instant.now())).orElseThrow(()->new ResponseStatusException(HttpStatus.BAD_REQUEST,"Invitation is invalid, expired, or already used."));var email=r.email().trim().toLowerCase();if(!invite.email.equals(email))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Use the email address that received this invitation.");var user=users.findByEmailIgnoreCase(email).orElseGet(()->users.save(new AppUser(r.fullName().trim(),email,passwords.encode(r.password()))));var membership=members.findByUserIdAndOrganizationId(user.id,invite.organizationId).orElseGet(()->members.save(new Membership(user.id,invite.organizationId,invite.role)));membership.role=invite.role;invite.acceptedAt=Instant.now();var refresh=issueRefresh(user);return new TokenResponse(tokens.access(user),refresh,"Bearer",props.accessMinutes()*60);}
private String issueRefresh(AppUser user){var raw=tokens.opaque();refreshes.save(new RefreshSession(user.id,tokens.hash(raw),Instant.now().plusSeconds(props.refreshDays()*86400)));return raw;}}
